if(driving&&stage>0&&stage<3&&Math.hypot(car.x-target.x,car.y-target.y)<75&&Math.abs(car.v)<70){stage++;if(stage===2){target={x:200,y:1250};toast('PACKAGE COLLECTED · Head to Palm Club')}else{cash+=750;toast('DELIVERY COMPLETE · +$750')}objective();log('mission_checkpoint',{stage})}
